def page(file,title,body,lab=False,description=None):
    desc=description or 'Hongpeng Zhou, Dame Kathleen Ollerenshaw Fellow at The University of Manchester. Machine learning, Bayesian learning, interpretable AI and bioinformatics.'
    nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+f'>{t}</a>' for f,t in NAV)
    text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Hongpeng Zhou</title><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#4e357a"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"></head><body><a class="skip-link" href="#main">Skip to main content</a><header><div class="header-inner"><a class="brand" href="index.html">Hongpeng Zhou<span>University of Manchester</span></a><nav aria-label="Main navigation">{nav}</nav></div></header><div class="layout">{side(lab)}<main id="main"><div class="eyebrow">{'HEALTH AI LAB' if lab else 'RESEARCH · MANCHESTER'}</div><h1>{E(title)}</h1>{body}</main></div><footer><div>© 2026 Hongpeng Zhou <span>·</span> Health AI Lab</div><div><a href="mailto:{email}">Contact</a><a href="https://github.com/hongpengzhou56/hongpengzhou56.github.io">GitHub</a><a href="https://www.hongpengzhou.com/">Original website</a></div></footer></body></html>'''
    (OUT/file).write_text(text,encoding='utf8')
def news(bs):
    out='<div class="news-list">'
    for b in bs:
        m=re.match(r'\[([^\]]+)\]:?\s*(.*)',b['text'])
        if not m:continue
        date=m[1].replace('-',' '); date=re.sub(r'\b(\d{2})$',r'20\1',date).replace('July','Jul')
        c=dict(b,text=m[2]); out+=f'<article class="news-item"><div class="news-date">{E(date)}</div><div>{rich(c)}</div></article>'
    return out+'</div>'
home='''<p class="intro">I am a <a href="https://research.manchester.ac.uk/en/persons/hongpeng-zhou/">Dame Kathleen Ollerenshaw Fellow</a> (Assistant Professor) in the Department of Computer Science at <a href="https://www.manchester.ac.uk/">The University of Manchester</a>.</p><p>I lead <a href="lab.html">Health AI Lab</a>, where we develop interpretable, efficient and practically useful AI methods for biomedical research. Our aim is to uncover the biological mechanisms behind complex biomedical data and help translate machine learning into biomedical discovery.</p><p>My research interests include <strong>machine learning, sparse Bayesian learning, interpretable learning and bioinformatics</strong>.</p><div class="quick-links"><a href="https://research.manchester.ac.uk/en/persons/hongpeng-zhou/">University profile</a><a href="lab.html">Our research group</a><a href="people.html">Group members</a></div><div class="notice"><strong>Interested in joining us?</strong><p>We welcome enquiries from prospective PhD students, postdoctoral researchers and visiting PhD students.</p><a href="join.html">Explore opportunities</a><a href="https://forms.gle/Lb5VEhT4vzHMJL1q6">PhD enquiry form ↗</a></div><div class="section-heading"><h2>Recent news</h2><a href="news.html">All news</a></div>'''+news(D['home'][12:18])+'''<h2>Background</h2><div class="timeline"><article><div class="period">2021 – 2023</div><h3>Postdoctoral Research Associate · University of Manchester</h3>'''+para(D['home'][39])+'''</article><article><div class="period">2018 – 2022</div><h3>PhD · Delft University of Technology</h3>'''+para(D['home'][41])+'''</article><article><div class="period">2011 – 2017</div><h3>Bachelor’s &amp; Master’s · Harbin Institute of Technology</h3>'''+para(D['home'][43])+'''</article></div>'''
page('index.html','Short bio',home)
page('news.html','News', '<p class="lede">Research, people and updates from our group.</p><h2>2026</h2>'+news(D['home'][12:22])+'<h2>2025</h2>'+news(D['home'][22:37])+'<h2>2024 & earlier</h2><p class="muted">Archived announcements; recruitment and funding calls may have closed.</p>'+news(D['home'][45:]))
lab='''<p class="intro">Interpretable and efficient AI for biomedical discovery.</p><p>Health AI Lab is led by <a href="index.html">Dr Hongpeng Zhou</a> in the Department of Computer Science at The University of Manchester. We develop machine learning methods to understand complex biomedical data and the biological mechanisms they reveal.</p><h2>Research directions</h2><div class="research-list"><article><span class="number">01</span><div><h3>Machine learning for biomedicine</h3><p>AI methods for single-cell transcriptomics, spatial omics and imaging mass cytometry, including foundation models and batch effect correction.</p></div></article><article><span class="number">02</span><div><h3>Interpretable &amp; Bayesian learning</h3><p>Sparse Bayesian methods, interpretable neural networks and learning approaches that reveal structure and mechanisms in data.</p></div></article><article><span class="number">03</span><div><h3>Efficient learning &amp; dynamical systems</h3><p>Neural architecture search, network compression and system identification, connecting machine learning with scientific and engineering applications.</p></div></article></div><h2>Our people</h2><p>Our group brings together postdoctoral researchers, PhD students and collaborators working across machine learning, biomedical science and engineering.</p><div class="quick-links"><a href="people.html">Meet the group</a><a href="publications.html">Read our publications</a></div><div class="notice"><strong>Join Health AI Lab</strong><p>Interested in developing AI methods for fundamental biomedical research challenges?</p><a href="join.html">Opportunities &amp; enquiries</a></div><div class="section-heading"><h2>Latest from the lab</h2><a href="news.html">All news</a></div>'''+news(D['home'][12:16])
page('lab.html','Health AI Lab',lab,True,'Health AI Lab at The University of Manchester, led by Hongpeng Zhou. Interpretable and efficient AI for biomedical discovery.')
def members(bs):
    out='<div class="member-list">'
    for b in bs:
        name,_,detail=b['text'].partition(',')
        if name=='Man Hou Lee':continue
        name=name.replace('ManHou Lee','Man Hou Lee')
        name_html=E(name)
        for a in b['links']:
            if a['text'].strip()==name: name_html=f'<a href="{E(url(a["url"]))}">{E(name)}</a>'
        out+='<article><h3>'+name_html+'</h3><p>'+rich(dict(b,text=detail.strip()))+'</p></article>'
    return out+'</div>'
