recent=[('Foundation Models in Omics Research: A Comprehensive Survey','Briefings in Bioinformatics · Accepted, July 2026',''),('Towards embodied AI in manufacturing: Review, Evaluation, and Future directions','Robotics and Computer-Integrated Manufacturing · 2026',''),('Will predictive AI make discovery research in metabolism obsolete?','npj Metabolic Health and Disease · 2026',''),('Benchmarking a Spatial-Aware Foundation Model: An Empirical Evaluation of CellPLM in Transcriptomics','CIBB 2026 · Oral presentation accepted',''),('Domain-adaptive nonlinear probabilistic latent variable model for vibration-based structural damage detection under climate change','Structural Health Monitoring · 2026',''),('Cross-Scale Contrastive Learning with Subgraph and Line-Graph Views for link prediction','Physica A: Statistical Mechanics and its Applications · 2026',''),('Improved Extended Kalman Filter-Based Disturbance Observers for Exoskeletons','IEEE Transactions on Industrial Electronics · Accepted, February 2026',''),('Rethinking RoPE: A Mathematical Blueprint for N-dimensional Positional Encoding','arXiv preprint · 2025','https://arxiv.org/abs/2504.06308'),('BioBatchNet: A Dual-Encoder Framework for Robust Batch Effect Correction in Imaging Mass Cytometry','bioRxiv preprint · 2025','https://www.biorxiv.org/content/10.1101/2025.03.15.643447v1'),('Machine learning-guided process optimization and comprehensive evaluation of additively manufactured biodegradable Zn-2Cu alloy','Journal of Materials Science and Technology · 2025','https://www.sciencedirect.com/science/article/pii/S1005030225003263'),('ELF autoencoder for unsupervised exploration of flat-band materials using electronic band structure fingerprints','Communications Physics · 2025','https://www.nature.com/articles/s42005-025-01936-2'),('Hierarchical Physics-Informed Neural Network for Rotor System Health Assessment','IEEE Transactions on Automation Science and Engineering · Accepted, January 2025','')]
